import{_ as r,o,c as s,af as a}from"./chunks/framework.B28LkSoM.js";const c=JSON.parse('{"title":"JavaWeb课程导学","description":"2025 版 JavaWeb+AI 课程导学：AI 时代的开发方式、什么是 Web、课程 6 大部分与每部分的 AI 切入点、课程特色与收获","frontmatter":{"title":"JavaWeb课程导学","published":"2026-09-29T00:00:00.000Z","description":"2025 版 JavaWeb+AI 课程导学：AI 时代的开发方式、什么是 Web、课程 6 大部分与每部分的 AI 切入点、课程特色与收获","tags":["JavaWeb","Web","AI辅助开发"],"image":"https://img.tsh520.cn/file/blog/post-covers/javaweb-01-course-intro.webp","order":1,"date":"2026-09-29T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/学习文档/JavaWeb学习笔记/01-JavaWeb课程导学.md","filePath":"posts/学习文档/JavaWeb学习笔记/01-JavaWeb课程导学.md"}'),n={name:"posts/学习文档/JavaWeb学习笔记/01-JavaWeb课程导学.md"};function e(g,t,d,l,i,p){return o(),s("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1790640000000"},[...t[0]||(t[0]=[a('<p>这篇是整套课程的&quot;地图&quot;：先讲清楚<strong>为什么这门课叫 JavaWeb+AI</strong>（AI 把哪几件事的效率拉开了），再讲<strong>什么是 Web</strong>、一个 Web 系统由哪三部分组成，最后是<strong>6 大部分课程安排</strong>、每部分对应哪个 AI 切入点，以及学完能拿到什么。</p><h2 id="ai-时代的开发方式" tabindex="-1">AI 时代的开发方式 <a class="header-anchor" href="#ai-时代的开发方式" aria-label="Permalink to &quot;AI 时代的开发方式&quot;">​</a></h2><p>课程开篇给的四句话，说的是 AI 已经切进了开发的每一个环节：</p><table tabindex="0"><thead><tr><th>环节</th><th>AI 时代怎么做</th></tr></thead><tbody><tr><td>编写代码</td><td>基础代码 <strong>AI 辅助编写</strong>，效率高，写的多</td></tr><tr><td>问题解决</td><td>基于 AI 解决复杂业务问题，<strong>优化程序、修复 Bug</strong></td></tr><tr><td>新技术学习</td><td>根据具体的需要结合着 AI，<strong>快速上手新技术</strong></td></tr><tr><td>分析设计</td><td>基于 AI <strong>设计数据库及业务方案</strong>，简单快捷</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">注意</p><p>PPT 上有一页新闻截图做例证：阿里云给通义灵码分配了正式员工工号 <strong>AI001</strong>，在内部全面推行 AI 编程，用通义灵码辅助写代码、读代码、查 Bug、优化代码；官方口径是&quot;公司未来 20% 的代码将由通义灵码编写，但程序员仍然是研发的核心&quot;，并且通义灵码已集成到 IDEA、VS Code 这些开发工具中。</p></div><p><img src="https://img.tsh520.cn/file/blog/article/02-%E9%98%BF%E9%87%8C%E4%BA%91AI001%E6%96%B0%E9%97%BB%E6%88%AA%E5%9B%BE.jpg" alt="阿里云 AI001 新闻截图"><em>图：课程用这则新闻说明&quot;AI 编程已经是企业里的日常&quot;——通义灵码被分配工号 AI001，在 IDEA、VS Code 等工具里辅助写代码、查 Bug、优化代码</em></p><h3 id="传统-java-课-vs-java-ai-课-四项能力对照" tabindex="-1">传统 Java 课 vs Java+AI 课：四项能力对照 <a class="header-anchor" href="#传统-java-课-vs-java-ai-课-四项能力对照" aria-label="Permalink to &quot;传统 Java 课 vs Java+AI 课：四项能力对照&quot;">​</a></h3><p>PPT 用一张表对比了两种课程练出来的能力（这一页在课上是一行一行展开的）：</p><table tabindex="0"><thead><tr><th>能力维度</th><th>传统 Java 课程</th><th>Java+AI 课程</th></tr></thead><tbody><tr><td>编码能力</td><td>手动编码能力较强（<strong>效率低</strong>）</td><td>手动编码能力较强（<strong>效率高</strong>）</td></tr><tr><td>问题解决</td><td>百度、问别人（<strong>弱</strong>）</td><td><strong>AI</strong>（强）</td></tr><tr><td>新技术学习应用</td><td>官网、百度（<strong>慢、效率低</strong>）</td><td><strong>效率高、准确度高</strong></td></tr><tr><td>业务分析设计</td><td><strong>无途径</strong>（较弱）</td><td><strong>较强</strong></td></tr></tbody></table><div class="important custom-block github-alert"><p class="custom-block-title">重要</p><p>注意两边的第一列都是&quot;<strong>手动编码能力较强</strong>&quot;——AI 课程<strong>不是</strong>不练基本功，而是基本功照练，只是把效率、问题解决、新技术学习、业务分析设计这四件事交给 AI 一起做。PPT 另外两句话把方向说得很直白：&quot;<strong>自身能力大幅提升</strong>&quot;&quot;<strong>软件变得更智能</strong>&quot;。</p></div><h2 id="什么是-web" tabindex="-1">什么是 Web <a class="header-anchor" href="#什么是-web" aria-label="Permalink to &quot;什么是 Web&quot;">​</a></h2><p><strong>Web：全球广域网，也称为万维网（www，World Wide Web），能够通过浏览器访问的网站。</strong></p><p>我们平时打开的网站就是 Web——淘宝、京东、唯品会这类电商页面，以及企业里各种管理系统，都算：</p><p><img src="https://img.tsh520.cn/file/blog/article/14-%E6%B7%98%E5%AE%9D%E9%A6%96%E9%A1%B5.jpg" alt="淘宝首页"><em>图：电商网站（淘宝）——首页上的分类、轮播、商品卡片、登录入口，都是&quot;前端程序&quot;展示出来的界面</em></p><p><img src="https://img.tsh520.cn/file/blog/article/14-%E4%BA%AC%E4%B8%9C%E9%A6%96%E9%A1%B5.jpg" alt="京东首页"><em>图：电商网站（京东）——课上直接拿 <code>https://www.jd.com</code> 举例，它就是通过浏览器访问的 Web 网站</em></p><p><img src="https://img.tsh520.cn/file/blog/article/14-%E5%94%AF%E5%93%81%E4%BC%9A%E9%A6%96%E9%A1%B5.jpg" alt="唯品会首页"><em>图：电商网站（唯品会）——同一个&quot;Web&quot;的另一种页面风格</em></p><p><img src="https://img.tsh520.cn/file/blog/article/15-%E5%AE%A2%E8%BE%BE%E5%A4%A9%E4%B8%8B%E4%BC%81%E4%B8%9A%E7%AE%A1%E7%90%86%E7%B3%BB%E7%BB%9F.jpg" alt="客达天下企业管理系统"><em>图：企业管理系统（客达天下）——后台类网站的典型长相：左侧菜单 + 顶部筛选 + 数据卡片</em></p><p><img src="https://img.tsh520.cn/file/blog/article/15-%E5%85%83%E5%9D%A4WMS%E4%BB%93%E5%82%A8%E7%AE%A1%E7%90%86%E7%B3%BB%E7%BB%9F.jpg" alt="元坤WMS仓储管理系统"><em>图：仓储管理系统（元坤 WMS）——带搜索表单、批量操作按钮、分页表格，这门课后半段做的项目就是这类界面</em></p><h2 id="一个-web-系统的三部分" tabindex="-1">一个 Web 系统的三部分 <a class="header-anchor" href="#一个-web-系统的三部分" aria-label="Permalink to &quot;一个 Web 系统的三部分&quot;">​</a></h2><p>PPT 把 <code>https://www.jd.com</code> 拆成三层来讲：</p><table tabindex="0"><thead><tr><th>部分</th><th>干什么</th></tr></thead><tbody><tr><td>前端程序</td><td><strong>界面展示</strong></td></tr><tr><td>服务端程序</td><td><strong>业务逻辑处理</strong></td></tr><tr><td>数据库</td><td><strong>数据存储和管理</strong></td></tr></tbody></table><ul><li>你在浏览器里看到的一切（商品图、价格、按钮）是<strong>前端程序</strong>画出来的；</li><li>点&quot;加入购物车&quot;&quot;提交订单&quot;之后要先经过<strong>服务端程序</strong>，由它做校验、算价格、写订单；</li><li>商品、用户、订单这些数据最终落在<strong>数据库</strong>里。</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">提示</p><p>这门课的 6 大部分正好是按这三层铺开的：<strong>前端</strong>（HTML/CSS/JS/Vue）→ <strong>服务端</strong>（Maven/HTTP/SpringBoot/MyBatis）→ <strong>数据库</strong>（MySQL）→ 最后把三层合起来<strong>部署</strong>上线。</p></div><h2 id="课程安排-6-大部分与各自的-ai-切入点" tabindex="-1">课程安排：6 大部分与各自的 AI 切入点 <a class="header-anchor" href="#课程安排-6-大部分与各自的-ai-切入点" aria-label="Permalink to &quot;课程安排：6 大部分与各自的 AI 切入点&quot;">​</a></h2><p>PPT 的这一页把课程分成 6 个 part，每个 part 都配了一个 AI 切入点（下面这张表按 PPT 上的编号顺序整理）：</p><table tabindex="0"><thead><tr><th>part</th><th>天数</th><th>学什么</th><th>AI 切入点</th></tr></thead><tbody><tr><td>part1 前端 Web 基础</td><td>2 天</td><td>HTML、CSS、JS、Ajax/Axios、Vue3</td><td><strong>AI 辅助设计页面</strong></td></tr><tr><td>part2 后端 Web 基础</td><td>4 天</td><td>Maven、HTTP、IOC、DI、MySQL、JDBC、MyBatis</td><td><strong>AI 辅助编码、单元测试</strong></td></tr><tr><td>part3 后端 Web 实战</td><td>6 天</td><td>部门管理、员工管理、班级管理、学员管理、报表统计、登录认证…</td><td><strong>AI 辅助编码、程序优化、Bug 修复</strong></td></tr><tr><td>part4 后端 Web 进阶</td><td>2 天</td><td>AOP、SpringBoot 原理、自定义 Starter、Maven 高级</td><td><strong>AI 辅助解释代码</strong></td></tr><tr><td>part5 前端 Web 实战</td><td>4 天</td><td>Vue 工程化、ElementPlus、Tlias 案例</td><td><strong>AI 辅助前端开发</strong></td></tr><tr><td>part6 部署</td><td>2 天</td><td>Linux、Docker</td><td><strong>AI 编写部署脚本</strong></td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">提示</p><p>记住这个顺序：<strong>先前端（看得见）→ 再后端（干活的）→ 再实战串起来 → 再进阶原理 → 再前端实战做完整项目 → 最后部署上线</strong>。本课程笔记的编号也是按这个顺序往后排的。</p></div><h2 id="课程特色" tabindex="-1">课程特色 <a class="header-anchor" href="#课程特色" aria-label="Permalink to &quot;课程特色&quot;">​</a></h2><p>PPT 用 4 个关键词总结课程的设计：</p><ol><li><strong>项目驱动式教学</strong>：以实战项目贯穿整套课程体系，项目含量占比达 <strong>80%</strong>，即学即用，在实战中掌握 Web 开发核心技术。</li><li><strong>打造全链路精英</strong>：基于 <strong>SpringBoot3 + Vue3</strong> 最新技术栈实战开发，全方位覆盖项目开发的 <strong>6 大环节</strong>——需求分析、设计、前后端开发、联调测试、最终部署。</li><li><strong>AI 赋能高效开发</strong>：整个课程阶段，从设计、编码、测试到 Bug 修复、程序优化全面拥抱 AI。</li><li><strong>企业级开发规范</strong>：基于当前主流的<strong>前后端分离</strong>开发模式，从需求分析 → 表结构设计 → 接口文档（<strong>30+</strong> 个）→ 功能实现 → 测试联调 → 部署，全方位模拟真实企业开发。</li></ol><p>这 4 条在 PPT 上各自配了截图，正好代表项目里的几个阶段：</p><p><img src="https://img.tsh520.cn/file/blog/article/20-Tlias%E5%91%98%E5%B7%A5%E7%AE%A1%E7%90%86%E9%A1%B5%E9%9D%A2.jpg" alt="Tlias员工管理页面"><em>图：贯穿课程的实战项目 Tlias 智能学习辅助系统——员工管理页面（项目驱动式教学的主案例）</em></p><p><img src="https://img.tsh520.cn/file/blog/article/20-Tlias%E5%AD%A6%E5%91%98%E7%AE%A1%E7%90%86%E9%A1%B5%E9%9D%A2.jpg" alt="Tlias学员管理页面"><em>图：Tlias 的学员管理页面——同样的&quot;搜索表单 + 批量按钮 + 分页表格&quot;结构，换成另一张业务表</em></p><p><img src="https://img.tsh520.cn/file/blog/article/20-Tlias%E6%95%B0%E6%8D%AE%E7%BB%9F%E8%AE%A1%E6%8A%A5%E8%A1%A8.jpg" alt="Tlias数据统计报表"><em>图：Tlias 的数据统计页（员工职位统计柱状图、员工性别统计环形图）——报表统计也是后端的实战内容</em></p><p><img src="https://img.tsh520.cn/file/blog/article/21-%E5%91%98%E5%B7%A5%E7%AE%A1%E7%90%86%E9%9C%80%E6%B1%82%E6%8F%8F%E8%BF%B0%E6%96%87%E6%A1%A3.jpg" alt="员工管理需求描述文档"><em>图：企业级开发规范里的第一环——&quot;员工管理-需求描述&quot;，连字段名、必填、类型、长度限制、输入限制都写清楚（这是写代码之前的依据）</em></p><p><img src="https://img.tsh520.cn/file/blog/article/21-Docker%E9%83%A8%E7%BD%B2%E9%A1%B9%E7%9B%AE%E6%88%AA%E5%9B%BE.jpg" alt="Docker部署项目截图"><em>图：最后的部署环节——在服务器上用 docker compose 构建镜像、起 mysql / tlias-server / nginx 三个容器</em></p><p><img src="https://img.tsh520.cn/file/blog/article/22-%E6%8E%A5%E5%8F%A3%E6%96%87%E6%A1%A3%E7%A4%BA%E4%BE%8B.jpg" alt="接口文档示例"><em>图：前后端分离开发的核心产物——接口文档（请求路径、请求方式、响应数据的 code/msg/data 结构），课程里会写 30+ 个这样的接口</em></p><h2 id="课程收获" tabindex="-1">课程收获 <a class="header-anchor" href="#课程收获" aria-label="Permalink to &quot;课程收获&quot;">​</a></h2><p>学完这门课，四个方向的能力都会有（PPT 的四条 + 一句总括）：</p><table tabindex="0"><thead><tr><th>收获</th><th>说明</th></tr></thead><tbody><tr><td>前端项目开发能力</td><td>会写页面、会用 Vue3 做前端工程</td></tr><tr><td>服务端接口开发能力</td><td>会用 SpringBoot 写接口给前端调用</td></tr><tr><td>数据库设计、应用能力</td><td>会设计表结构、会用 MySQL 存取数据</td></tr><tr><td>前后端项目部署能力</td><td>会用 Linux + Docker 把项目部署上线</td></tr></tbody></table><p>总括一句：<strong>具备基于 SpringBoot3 + Vue3 设计、开发、部署单体项目的能力</strong>——直接对得上三个用途：<strong>毕业设计、找实习、开发项目</strong>。</p><p>PPT 上展示的项目形态是这样的：</p><p><img src="https://img.tsh520.cn/file/blog/article/25-iHRM%E4%BA%BA%E5%8A%9B%E8%B5%84%E6%BA%90%E7%B3%BB%E7%BB%9F.jpg" alt="iHRM人力资源系统"><em>图：企业后台系统（iHRM 人力资源管理系统）——表格 + 部门筛选 + 权限菜单</em></p><p><img src="https://img.tsh520.cn/file/blog/article/25-%E7%95%85%E8%B4%AD%E5%95%86%E5%9F%8E%E9%A6%96%E9%A1%B5.jpg" alt="畅购商城首页"><em>图：电商网站（畅购商城）——首页导航、分类、轮播、商品楼层</em></p><p><img src="https://img.tsh520.cn/file/blog/article/25-%E8%B4%9D%E5%A3%B3%E6%89%BE%E6%88%BF%E7%A7%BB%E5%8A%A8%E7%AB%AF%E9%A1%B5%E9%9D%A2.jpg" alt="贝壳找房移动端页面"><em>图：移动端页面（贝壳找房 App 首页）——同一套前端技术也能做移动端页面</em></p><h2 id="答疑途径" tabindex="-1">答疑途径 <a class="header-anchor" href="#答疑途径" aria-label="Permalink to &quot;答疑途径&quot;">​</a></h2><p>PPT 的&quot;答疑途径&quot;一页放的就是课程群/评论区的实际提问与回复：</p><p><img src="https://img.tsh520.cn/file/blog/article/26-%E7%AD%94%E7%96%91%E6%8F%90%E9%97%AE%E4%B8%8E%E8%A7%A3%E7%AD%94%E6%88%AA%E5%9B%BE.jpg" alt="答疑提问与解答截图"><em>图：课上举的答疑例子——学员私信问&quot;MyBatis 里 <code>@Delete</code> 注解的 <code>#{id}</code> 报红线&quot;，回复是&quot;右键 → Uninject language，去掉语言注入后重新选择&quot;</em></p><div class="tip custom-block github-alert"><p class="custom-block-title">提示</p><p>学习建议就藏在整篇导学里：<strong>基础代码自己写、卡住的知识点让 AI 解释、重复代码交给 AI 生成、真实项目按&quot;需求 → 表结构 → 接口 → 代码 → 测试 → 部署&quot;的顺序做完</strong>。这也是后面每一篇笔记都在用的节奏。</p></div><h2 id="小结-导学回顾" tabindex="-1">小结（导学回顾） <a class="header-anchor" href="#小结-导学回顾" aria-label="Permalink to &quot;小结（导学回顾）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>答案</th></tr></thead><tbody><tr><td>什么是 Web？</td><td>全球广域网，也称万维网（www，World Wide Web），<strong>能够通过浏览器访问的网站</strong></td></tr><tr><td>一个网站由哪几部分组成？</td><td><strong>前端程序</strong>（界面展示）、<strong>服务端程序</strong>（业务逻辑处理）、<strong>数据库</strong>（数据存储和管理）</td></tr><tr><td>Java+AI 课程比传统 Java 课强在哪？</td><td>编码效率、问题解决（用 AI）、新技术学习应用、业务分析设计四项</td></tr><tr><td>课程一共几部分？各几天？</td><td>6 部分：前端基础 2 天 + 后端基础 4 天 + 后端实战 6 天 + 后端进阶 2 天 + 前端实战 4 天 + 部署 2 天</td></tr><tr><td>项目占课程多少比重？</td><td>80%（项目驱动式教学）</td></tr><tr><td>学完能做什么？</td><td>基于 SpringBoot3 + Vue3 <strong>设计、开发、部署单体项目</strong>；写毕业设计、找实习、做项目</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/posts/编程学习/javaweb学习笔记/02-web前端初识/">Web前端初识</a></li></ul><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><h3 id="一、知识回顾-读完直接做下面的实践题" tabindex="-1">一、知识回顾（读完直接做下面的实践题） <a class="header-anchor" href="#一、知识回顾-读完直接做下面的实践题" aria-label="Permalink to &quot;一、知识回顾（读完直接做下面的实践题）&quot;">​</a></h3><ol><li>Web 的定义：<strong>全球广域网</strong>，也称为<strong>万维网</strong>（www，World Wide Web），指<strong>能够通过浏览器访问的网站</strong></li><li>AI 时代的开发方式体现在四个环节：<strong>编写代码</strong>（基础代码 AI 辅助编写，效率高）、<strong>问题解决</strong>（解决复杂业务、优化程序、修复 Bug）、<strong>新技术学习</strong>（结合 AI 快速上手）、<strong>分析设计</strong>（设计数据库及业务方案）</li><li>传统 Java 课与 Java+AI 课的四项能力对照：编码能力上两边都是&quot;<strong>手动编码能力较强</strong>&quot;，差别在<strong>效率</strong>（传统低 / AI 课高）；问题解决（百度问人 vs <strong>AI</strong>）、新技术学习应用（官网百度 vs <strong>效率高、准确度高</strong>）、业务分析设计（<strong>无途径</strong> vs <strong>较强</strong>）</li><li>一个 Web 系统由三部分组成：<strong>前端程序</strong>负责<strong>界面展示</strong>、<strong>服务端程序</strong>负责<strong>业务逻辑处理</strong>、<strong>数据库</strong>负责<strong>数据存储和管理</strong></li><li>课程分 6 个 part：part1 <strong>前端 Web 基础（2 天）</strong>、part2 <strong>后端 Web 基础（4 天）</strong>、part3 <strong>后端 Web 实战（6 天）</strong>、part4 <strong>后端 Web 进阶（2 天）</strong>、part5 <strong>前端 Web 实战（4 天）</strong>、part6 <strong>部署（2 天）</strong></li><li>part1 学 <strong>HTML、CSS、JS、Ajax/Axios、Vue3</strong>，AI 切入点是 <strong>AI 辅助设计页面</strong>；part2 学 <strong>Maven、HTTP、IOC、DI、MySQL、JDBC、MyBatis</strong>，AI 切入点是 <strong>AI 辅助编码、单元测试</strong></li><li>part3 做<strong>部门管理、员工管理、班级管理、学员管理、报表统计、登录认证</strong>，AI 切入点 <strong>AI 辅助编码、程序优化、Bug 修复</strong>；part4 学 <strong>AOP、SpringBoot 原理、自定义 Starter、Maven 高级</strong>，AI 切入点 <strong>AI 辅助解释代码</strong></li><li>part5 学 <strong>Vue 工程化、ElementPlus、Tlias 案例</strong>，AI 切入点 <strong>AI 辅助前端开发</strong>；part6 学 <strong>Linux、Docker</strong>，AI 切入点 <strong>AI 编写部署脚本</strong></li><li>课程特色四条：<strong>项目驱动式教学</strong>（项目占比 <strong>80%</strong>）、<strong>打造全链路精英</strong>（SpringBoot3+Vue3，覆盖项目开发 <strong>6 大环节</strong>）、<strong>AI 赋能高效开发</strong>、<strong>企业级开发规范</strong>（需求分析 → 表结构设计 → 接口文档 <strong>30+</strong> → 功能实现 → 测试联调 → 部署）</li><li>课程收获四项能力：<strong>前端项目开发能力</strong>、<strong>服务端接口开发能力</strong>、<strong>数据库设计应用能力</strong>、<strong>前后端项目部署能力</strong>；总目标是具备基于 <strong>SpringBoot3 + Vue3</strong> 设计、开发、部署<strong>单体项目</strong>的能力，可直接用于<strong>毕业设计、找实习、开发项目</strong></li></ol><h3 id="二、概念自测" tabindex="-1">二、概念自测 <a class="header-anchor" href="#二、概念自测" aria-label="Permalink to &quot;二、概念自测&quot;">​</a></h3><ul><li><p>[ ] <strong>2-1 用一句话解释&quot;什么是 Web&quot;</strong> 要求：说出它的两个别称（全球广域网 / 万维网）+ 判断标准。</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：定义里最关键的是&quot;用什么访问&quot; <strong>二级 · 角度</strong>：它是不是一个网站？访问它的工具是什么？ <strong>三级 · 骨架</strong>：Web 是 ______，也称为 ______，是能够通过 ______ 访问的网站。</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-1</strong> Web 是全球广域网，也称万维网（www，World Wide Web），指<strong>能够通过浏览器访问的网站</strong>。判断标准就是&quot;能不能用浏览器打开&quot;。</p></details></li><li><p>[ ] <strong>2-2 同一个网站（比如 jd.com）由哪三部分组成？各负责什么？</strong> 要求：说出三部分的名字和职责，并各举一个&quot;如果没有它会怎样&quot;。</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：从&quot;用户看到什么、谁来算业务、谁来存数据&quot;这三个角度各想一层</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-2</strong> 三部分是<strong>前端程序</strong>（界面展示）、<strong>服务端程序</strong>（业务逻辑处理）、<strong>数据库</strong>（数据存储和管理）。没有前端程序就看不到页面；没有服务端程序，点&quot;提交订单&quot;没人处理业务规则；没有数据库，商品和订单无处存放、刷新就没了。</p></details></li><li><p>[ ] <strong>2-3 判断题：Java+AI 课程里&quot;手动编码能力变弱了，靠 AI 就行&quot;——对吗？为什么？</strong> 要求：先判断对错，再用 PPT 里的一句原话反驳或支持它。</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：回到 PPT 里&quot;传统 Java 课 vs Java+AI 课&quot;的那张对照表，先看&quot;编码能力&quot;这一栏写的是什么</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-3</strong> 错。对照表里传统课程和 Java+AI 课程的&quot;编码能力&quot;这一栏写的都是&quot;<strong>手动编码能力较强</strong>&quot;，区别只在括号里的<strong>效率</strong>（传统效率低、AI 课效率高）。AI 是帮你在<strong>问题解决、新技术学习、业务分析设计</strong>这几栏拉开差距，不是替你跳过基本功。</p></details></li><li><p>[ ] <strong>2-4 按顺序说出这门课 6 个 part 的名字，并说出 part1 和 part6 各自的 AI 切入点</strong> 要求：顺序不能乱；AI 切入点用&quot;AI 辅助 XX&quot;的说法。</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：按课程讲的先后顺序数一遍（基础 → 实战 → 进阶 → 部署），注意别漏掉最后两个 part</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-4</strong> 顺序是：<strong>前端 Web 基础（2 天）→ 后端 Web 基础（4 天）→ 后端 Web 实战（6 天）→ 后端 Web 进阶（2 天）→ 前端 Web 实战（4 天）→ 部署（2 天）</strong>。part1 的 AI 切入点是&quot;<strong>AI 辅助设计页面</strong>&quot;，part6 的 AI 切入点是&quot;<strong>AI 编写部署脚本</strong>&quot;。</p></details></li></ul>',58)])])}const u=r(n,[["render",e]]);export{c as __pageData,u as default};
